/* =========================================================
   FILIN MASTER PRODUCT V3 PROFILE — SIRIUS KT150
   V1.2 LEGACY GALLERY HYDRATOR
   Fixes encoded Tilda gallery JSON such as:
   &quot;li_img&quot;:&quot;https://static.tildacdn.com/...&quot;
   and restores only valid absolute CDN image URLs.
   Frozen Golden Standard core is not modified.
   ========================================================= */
(function(){
  'use strict';

  var SLUG='audioinstrument_sirius_kt150_tube_amplifier';
  var LEGACY_URL='/audioinstrument_sirius_kt150_tube_amplifier';
  var LEGACY_GALLERY_REC='rec2355175041';
  var started=false;

  function decodeEntities(value){
    var s=String(value==null?'':value);
    if(!s) return '';
    var ta=document.createElement('textarea');
    ta.innerHTML=s;
    return ta.value;
  }

  function normalizeCandidate(raw){
    if(!raw) return '';
    var s=decodeEntities(raw).trim();
    s=s.replace(/\\\//g,'/').replace(/\\u002f/gi,'/');
    s=s.replace(/^url\((['"]?)/i,'').replace(/(['"]?)\)$/,'');

    /* If Tilda serialized an entire JSON fragment into an attribute,
       discard the JSON key and keep the actual CDN URL only. */
    var absolute=s.indexOf('https://');
    if(absolute<0) absolute=s.indexOf('http://');
    if(absolute>0) s=s.slice(absolute);
    if(s.indexOf('//')===0) s='https:'+s;

    /* This profile accepts only real absolute image URLs. Never allow
       URL() to turn malformed JSON into https://filinlabs.com/<junk>. */
    if(!/^https?:\/\//i.test(s)) return '';

    /* Stop at serialized JSON / HTML delimiters. */
    s=s.split(/["'<>\s\\,}\]]/)[0];
    s=s.replace(/[);]+$/,'');
    return s;
  }

  function looksLikeProductImage(u){
    if(!u) return false;
    if(!/^https?:\/\/(?:static|thb)\.tildacdn\.com\//i.test(u) &&
       !/\.(?:jpe?g|png|webp|gif|avif)(?:[?#]|$)/i.test(u)) return false;
    /* Shared placeholder/logo image from the catalog is not a Sirius photo. */
    if(/______100-Photoroom\.png/i.test(u)) return false;
    if(/(?:blank\.gif|empty\.png|pixel|favicon|icon-)/i.test(u)) return false;
    return true;
  }

  function pushUrl(list,seen,raw){
    var u=normalizeCandidate(raw);
    if(!looksLikeProductImage(u)) return;
    var key=u.replace(/[?#].*$/,'');
    if(seen[key]) return;
    seen[key]=1;
    list.push(u);
  }

  function addRaw(list,seen,raw){
    if(!raw) return;
    var decoded=decodeEntities(raw).replace(/\\\//g,'/').replace(/\\u002f/gi,'/');

    /* First extract every CDN URL embedded inside JSON, srcset or CSS. */
    var rx=/https?:\/\/(?:static|thb)\.tildacdn\.com\/[^"'<>\s\\,}\]]+/gi;
    var m, found=false;
    while((m=rx.exec(decoded))){
      found=true;
      pushUrl(list,seen,m[0]);
    }

    /* Then handle a normal single URL / srcset token. */
    if(!found){
      decoded.split(',').forEach(function(part){
        var token=part.trim().split(/\s+/)[0];
        pushUrl(list,seen,token);
      });
    }
  }

  function extractImages(doc){
    var list=[];
    var seen=Object.create(null);
    var rec=doc.getElementById(LEGACY_GALLERY_REC);
    var scope=rec || doc;

    var attrs=[
      'data-original','data-src','data-lazy-src','data-img-zoom-url',
      'data-bg','data-bg-img','data-original-src','src','srcset',
      'data-gallery-img','data-zoom-target','data-content-cover-bg'
    ];

    scope.querySelectorAll('*').forEach(function(el){
      attrs.forEach(function(a){
        if(el.hasAttribute && el.hasAttribute(a)) addRaw(list,seen,el.getAttribute(a));
      });

      /* Tilda Zero Block galleries often keep slide objects in data-* JSON. */
      if(el.attributes){
        Array.prototype.forEach.call(el.attributes,function(attr){
          if(attr && attr.value && /tildacdn\.com|li_img|imgurl|image/i.test(attr.value)){
            addRaw(list,seen,attr.value);
          }
        });
      }

      var style=el.getAttribute && el.getAttribute('style');
      if(style) addRaw(list,seen,style);
    });

    /* Finally scan serialized markup, but ONLY extract the absolute CDN URL
       itself. This is the V1.1 bug fix: never pass a whole JSON fragment. */
    addRaw(list,seen,scope.outerHTML||'');

    return list;
  }

  function applyImages(imgs){
    if(!imgs || !imgs.length) return false;
    var api=window.FilinMasterProductV3;
    if(!api || !api.profiles || !api.profiles[SLUG]) return false;
    var p=api.profiles[SLUG];
    p.overview=p.overview||{};
    var existing=Array.isArray(p.overview.galleryImages)?p.overview.galleryImages:[];

    var merged=[];
    var seen=Object.create(null);
    function push(u){
      u=normalizeCandidate(u);
      if(!looksLikeProductImage(u)) return;
      var k=u.replace(/[?#].*$/,'');
      if(seen[k]) return;
      seen[k]=1;
      merged.push(u);
    }

    existing.forEach(push);
    imgs.forEach(push);

    if(!merged.length) return false;
    p.overview.galleryImages=merged;
    if(typeof api.apply==='function') api.apply();
    console.info('[Master Product V3 Profile] SIRIUS COMPLETE GALLERY RESTORED V1.2',{
      images:merged.length,
      galleryImages:merged.slice()
    });
    return true;
  }

  function waitAndApply(imgs,tries){
    tries=tries||0;
    if(applyImages(imgs)) return;
    if(tries>=50) return;
    setTimeout(function(){ waitAndApply(imgs,tries+1); },100);
  }

  function start(){
    if(started) return;
    started=true;
    fetch(LEGACY_URL,{credentials:'same-origin',cache:'no-store'})
      .then(function(r){ if(!r.ok) throw new Error('HTTP '+r.status); return r.text(); })
      .then(function(html){
        var doc=new DOMParser().parseFromString(html,'text/html');
        var imgs=extractImages(doc);
        console.info('[Master Product V3 Profile] SIRIUS LEGACY GALLERY FOUND V1.2',{
          images:imgs.length,
          galleryImages:imgs.slice()
        });
        waitAndApply(imgs,0);
      })
      .catch(function(err){
        console.warn('[Master Product V3 Profile] SIRIUS LEGACY GALLERY SYNC FAILED V1.2',err);
      });
  }

  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',function(){ setTimeout(start,80); },{once:true});
  } else {
    setTimeout(start,80);
  }
})();
